export function getPYMLAProfile(acNo: number): MLAProfile | undefined {
  return PY_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getPYMLAsByParty(party: string): MLAProfile[] {
  return PY_MLA_PROFILES.filter(p => p.party === party);
}

export function getPYFemaleMLAs(): MLAProfile[] {
  return PY_MLA_PROFILES.filter(p => p.gender === 'F');
}
